arduino.globals:
const int latchPin_${COMP_SUFFIX} = 10;
const int clockPin_${COMP_SUFFIX} = 13;
const int dataPin_${COMP_SUFFIX} = 11;

arduino.setup:
pinMode(latchPin_${COMP_SUFFIX}, OUTPUT);
pinMode(clockPin_${COMP_SUFFIX}, OUTPUT);
pinMode(dataPin_${COMP_SUFFIX}, OUTPUT);

arduino.loop:
digitalWrite(latchPin_${COMP_SUFFIX}, LOW);
shiftOut(dataPin_${COMP_SUFFIX}, clockPin_${COMP_SUFFIX}, MSBFIRST, 255);
digitalWrite(latchPin_${COMP_SUFFIX}, HIGH);
delay(1000);
digitalWrite(latchPin_${COMP_SUFFIX}, LOW);
shiftOut(dataPin_${COMP_SUFFIX}, clockPin_${COMP_SUFFIX}, MSBFIRST, 0);
digitalWrite(latchPin_${COMP_SUFFIX}, HIGH);
delay(1000);
